<?php declare(strict_types=1); requireRole($user,['provincial_admin']); ?>
<section class="panel form-panel"><div class="section-kicker">ORGANIZE YOUR PROVINCE</div><h2>Assign church units in bulk</h2><p class="muted">Select multiple Areas to move to a Zone, or multiple Parishes to move to an Area or directly to a Zone. Moving an Area also moves its child parishes. Existing officer accounts and reports stay with their units; supervisory access follows the new parent on the next request.</p><form method="post" data-unit-bulk><?php hiddenAction('move_units') ?><div class="form-grid"><label>Destination zone or area<select name="destination_id" data-unit-search required><option value="">Search for the destination</option><?php foreach($nodes as $node):if($node['node_type']==='parish')continue; ?><option value="<?= (int)$node['id'] ?>"><?= e(unitLabel($node)) ?></option><?php endforeach ?></select></label><label>Filter units to select<input type="search" data-bulk-search placeholder="Type a name, parish code, parent or zone…" autocomplete="off"></label></div><div class="bulk-toolbar"><label>Unit level<select data-bulk-type><option value="">Areas and parishes</option><option value="area">Areas only</option><option value="parish">Parishes only</option></select></label><button type="button" class="secondary" data-bulk-all>Select visible units</button><button type="button" class="secondary" data-bulk-clear>Clear selection</button><span data-bulk-count role="status" aria-live="polite">0 selected</span></div><div class="unit-checklist" aria-label="Areas and parishes to assign"><?php foreach($nodes as $node):if($node['node_type']==='zone')continue; ?><label class="unit-check" data-unit-type="<?= e($node['node_type']) ?>"><input type="checkbox" name="unit_ids[]" value="<?= (int)$node['id'] ?>"><span><?= e(unitLabel($node)) ?></span></label><?php endforeach ?></div><p class="small muted" data-bulk-hint>Up to 500 units per assignment. Hidden selections are retained when filtering. Areas require a Zone destination; Parishes may use an Area or Zone. To move an Area and its children, select the Area only.</p><button class="primary">Assign selected units →</button></form></section>
<section class="panel form-panel"><h2>Upgrade a zone-planted parish to an Area</h2><p class="muted">Create an Area around a parish that is currently directly under a Zone. Its original parish record becomes the headquarters parish under the new Area, keeping the same code, officer accounts and historical reports. A separate Area representative account can then be provisioned.</p><form method="post" class="form-grid"><?php hiddenAction('upgrade_parish') ?><label>Direct zone parish<select name="parish_id" data-unit-search required><option value="">Search for a zone-planted parish</option><?php foreach($nodes as $node):if($node['node_type']!=='parish' || ($node['parent_type'] ?? '')!=='zone')continue; ?><option value="<?= (int)$node['id'] ?>"><?= e(unitLabel($node)) ?></option><?php endforeach ?></select></label><label>New Area name<input name="area_name" required maxlength="150" placeholder="e.g. Living Hope Area"></label><button class="primary">Create Area &amp; preserve parish history</button></form></section>
